<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\StoreDomain;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class DomainController extends Controller{public function index(){return view('admin.domains.index',['domains'=>StoreDomain::orderByDesc('primary')->latest()->get()]);}public function store(Request $r){$d=$r->validate(['domain'=>'required|string|max:255|unique:store_domains,domain']);$domain=strtolower(preg_replace('#^https?://#','',trim($d['domain'],'/ ')));StoreDomain::create(['domain'=>$domain,'primary'=>!StoreDomain::exists(),'verification_status'=>'pending','ssl_status'=>'pending']);return back()->with('success','Domain added. DNS verification is pending.');}public function primary(StoreDomain $domain){DB::transaction(function()use($domain){StoreDomain::where('primary',true)->update(['primary'=>false]);$domain->update(['primary'=>true]);});return back()->with('success','Primary domain updated.');}public function verify(StoreDomain $domain){$domain->update(['verification_status'=>'manual_review']);return back()->with('success','Domain queued for verification.');}public function destroy(StoreDomain $domain){abort_if($domain->primary,422,'Primary domain cannot be removed.');$domain->delete();return back()->with('success','Domain removed.');}}

